// Meta sends one webhook for many things: messages, delivery receipts, read receipts.
// Only inbound customer messages should ever reach the AI. Everything else stops here.
const body = $('WhatsApp message (POST)').first().json.body ?? {};
const out = [];

for (const entry of body.entry ?? []) {
  for (const change of entry.changes ?? []) {
    const value = change.value ?? {};
    const names = Object.fromEntries((value.contacts ?? []).map((c) => [c.wa_id, c.profile?.name ?? '']));
    for (const m of value.messages ?? []) {
      out.push({
        json: {
          messageId: m.id,
          from: m.from,
          name: names[m.from] ?? '',
          type: m.type,
          text: m.type === 'text' ? String(m.text?.body ?? '').slice(0, 2000) : null,
          receivedAt: new Date(Number(m.timestamp) * 1000 || Date.now()).toISOString(),
        },
      });
    }
  }
}

// Zero items is correct for a status-only webhook: nothing downstream should run.
return out;

// Meta retries a webhook if it doesn't get a 200 fast enough, so the same message can
// arrive twice. Without this, the customer gets two replies and the sheet gets two orders.
// Static data persists only for production (activated) executions — which is what Meta hits.
const store = $getWorkflowStaticData('global');
store.seen = store.seen ?? [];
const fresh = [];

for (const item of $input.all()) {
  if (store.seen.includes(item.json.messageId)) continue;
  store.seen.push(item.json.messageId);
  fresh.push(item);
}

store.seen = store.seen.slice(-1000);
return fresh;

// Ollama structured output: the model must return JSON matching this schema.
// It is still validated afterwards — a schema is a request, not a guarantee.
const cfg = $('Config').first().json;
const rp = (n) => 'Rp' + n.toLocaleString('id-ID');
const names = cfg.products.map((p) => p.name);

const system = `Kamu adalah asisten WhatsApp untuk ${cfg.businessName}.
Balas dalam Bahasa Indonesia yang ramah dan singkat (maksimal 3 kalimat).
Hanya gunakan informasi di bawah ini. Jangan mengarang harga, produk, ongkir, atau janji.
Kalau informasinya tidak ada, bilang admin akan membantu.

DAFTAR HARGA:
${cfg.products.map((p) => `- ${p.name}: ${rp(p.price)}`).join('\n')}
Ongkir: ${rp(cfg.shippingFlat)} flat, gratis untuk belanja minimal ${rp(cfg.freeShippingFrom)}.
${cfg.otherInfo}

Tentukan intent:
- order: pelanggan menyatakan ingin membeli produk tertentu ("mau pesan", "beli", "order")
- question: bertanya harga, ongkir, jam buka, cara bayar, dll. (bertanya ongkir BUKAN order)
- complaint: keluhan atau masalah pesanan
- other: sapaan atau lainnya
Untuk order: isi items dengan SETIAP produk yang dipesan (product persis dari daftar, quantity),
dan address bila disebut. Jika bukan order: items [] dan address "".`;

const format = {
  type: 'object',
  properties: {
    intent: { type: 'string', enum: ['order', 'question', 'complaint', 'other'] },
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: { product: { type: 'string', enum: names }, quantity: { type: 'integer' } },
        required: ['product', 'quantity'],
      },
    },
    address: { type: 'string' },
    reply: { type: 'string' },
  },
  required: ['intent', 'items', 'address', 'reply'],
};

return $input.all().map((item) => ({
  json: {
    ...item.json,
    aiRequest: {
      model: cfg.model,
      stream: false,
      options: { temperature: 0.1 },
      format,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: item.json.text },
      ],
    },
  },
}));

// The model's output is a suggestion, not a fact. Two rules:
//   1. Money is calculated here, in code — never by the model.
//   2. Any price the model writes must exist in the price list. Otherwise the customer
//      gets a holding reply and the owner is asked to answer.
// Model down, timeout, invalid JSON or an unknown intent end the same way: nobody is ghosted.
const INTENTS = ['order', 'question', 'complaint', 'other'];
const cfg = $('Config').first().json;
const msgs = $('Build AI request').all();
const rp = (n) => 'Rp' + n.toLocaleString('id-ID');
const FALLBACK = `Terima kasih sudah menghubungi ${cfg.businessName}! Pesan Anda sudah kami terima, admin kami akan membalas sebentar lagi.`;

const allowed = new Set([...cfg.products.map((p) => p.price), cfg.shippingFlat, cfg.freeShippingFrom]);
const pricesIn = (text) =>
  [...text.matchAll(/Rp\s?([\d.,]+)/gi)].map((m) => Number(m[1].replace(/[.,](?=\d{3}\b)/g, '').replace(/[.,]\d{1,2}$/, '')));

// The first word of each product name ("arabika", "robusta", "house") is enough to tell
// whether the customer mentioned it. Used to catch the model dropping part of an order.
const keyword = (p) => p.name.split(' ')[0].toLowerCase();

function orderReply(lines, address) {
  const subtotal = lines.reduce((sum, l) => sum + l.product.price * l.qty, 0);
  const shipping = subtotal >= cfg.freeShippingFrom ? 0 : cfg.shippingFlat;
  const out = [`Siap kak, pesanan dicatat 🙏`];
  for (const l of lines) out.push(`${l.qty} x ${l.product.name} = ${rp(l.product.price * l.qty)}`);
  out.push(`Ongkir: ${shipping ? rp(shipping) : 'GRATIS'}`, `Total: ${rp(subtotal + shipping)}`);
  out.push(address ? `Dikirim ke: ${address}` : `Boleh minta alamat lengkap pengirimannya kak?`);
  out.push(`Admin akan kirim info pembayaran (BCA/QRIS) sebentar lagi.`);
  return { reply: out.join('\n'), total: subtotal + shipping };
}

return $input.all().map((item, i) => {
  const msg = msgs[i].json;
  delete msg.aiRequest;
  let ai = null;
  let reply = FALLBACK;
  let total = '';
  let problem = '';

  try {
    if (item.json.error) throw new Error('AI request failed: ' + String(item.json.error.message ?? item.json.error).slice(0, 150));
    ai = JSON.parse(item.json.message?.content ?? '');
    if (!INTENTS.includes(ai.intent)) throw new Error(`unknown intent "${ai.intent}"`);

    if (ai.intent === 'order') {
      if (!Array.isArray(ai.items) || !ai.items.length) throw new Error('order with no items');
      const lines = ai.items.map((it) => {
        const product = cfg.products.find((p) => p.name === it.product);
        const qty = Number(it.quantity);
        if (!product) throw new Error(`order for a product not in the list: "${it.product}"`);
        if (!Number.isInteger(qty) || qty < 1 || qty > 50) throw new Error(`implausible quantity: ${it.quantity}`);
        return { product, qty };
      });
      // Cross-check the model's order against what the customer actually wrote. It has both
      // dropped an item (under-billing) and listed one twice (double-billing) in testing.
      const text = msg.text.toLowerCase();
      const numbers = new Set(text.match(/\d+/g) ?? []);
      const merged = [];
      for (const l of lines) {
        const same = merged.find((m) => m.product === l.product);
        if (same && same.qty !== l.qty) throw new Error(`AI listed ${l.product.name} twice with different quantities`);
        if (!same) merged.push(l); // an identical repeat is the model repeating itself
      }
      for (const l of merged) {
        if (!text.includes(keyword(l.product))) throw new Error(`AI added a product the customer didn't mention: ${l.product.name}`);
        if (l.qty !== 1 && !numbers.has(String(l.qty))) throw new Error(`quantity ${l.qty} for ${l.product.name} isn't in the message`);
      }
      const missed = cfg.products.filter((p) => text.includes(keyword(p)) && !merged.some((l) => l.product === p));
      if (missed.length) throw new Error(`AI dropped part of the order: ${missed.map((p) => p.name).join(', ')}`);
      lines.splice(0, lines.length, ...merged);
      ({ reply, total } = orderReply(lines, String(ai.address ?? '').trim()));
      ai.product = lines.map((l) => l.product.name).join(' + ');
      ai.quantity = lines.map((l) => l.qty).join(' + ');
      ai.orderLines = lines.map((l) => `${l.qty} x ${l.product.name}`).join('\n');
    } else {
      if (typeof ai.reply !== 'string' || !ai.reply.trim()) throw new Error('empty reply');
      if (ai.reply.length > 1000) throw new Error('reply too long');
      const invented = pricesIn(ai.reply).filter((n) => !allowed.has(n));
      if (invented.length) throw new Error(`AI quoted a price not in the price list: ${invented.map(rp).join(', ')}`);
      reply = ai.reply.trim();
    }
  } catch (e) {
    problem = String(e.message ?? e);
    ai = null;
    reply = FALLBACK;
  }

  const isOrder = ai?.intent === 'order';
  return {
    json: {
      ...msg,
      intent: ai ? ai.intent : 'needs_human',
      reply,
      product: isOrder ? ai.product : '',
      quantity: isOrder ? ai.quantity : '',
      address: isOrder ? ai.address ?? '' : '',
      total,
      orderLines: isOrder ? ai.orderLines : '',
      needsHuman: !ai || ai.intent === 'complaint',
      problem,
    },
  };
});

// Images, voice notes, stickers: don't guess at them with a text model. Hand off to a human.
const cfg = $('Config').first().json;
return $input.all().map((item) => ({
  json: {
    ...item.json,
    intent: 'needs_human',
    reply: `Terima kasih! Saat ini asisten kami hanya bisa membaca pesan teks. Admin ${cfg.businessName} akan cek pesan Anda segera.`,
    product: '', quantity: '', address: '', total: '',
    needsHuman: true,
    problem: `non-text message (${item.json.type})`,
  },
}));

// One row per message — the same columns a Google Sheet would get.
const esc = (v) => {
  const s = String(v ?? '').replace(/\r?\n/g, ' ');
  return /[",]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const cols = ['receivedAt', 'from', 'name', 'intent', 'product', 'quantity', 'address', 'total', 'text', 'reply', 'needsHuman', 'problem'];
const rows = $('All handled messages').all();
let lines = rows.map((i) => cols.map((c) => esc(i.json[c])).join(',')).join('\n') + '\n';

// New file (or someone deleted it): start with a header row. In Google Sheets the header
// row already exists, so this whole branch becomes a single "Append row" node there.
if (!$input.first().json.exists) lines = cols.join(',') + '\n' + lines;

return [{ json: { csv: lines } }];
